reference_css:
* { box-sizing: border-box; }
:root { --felt: #14532d; --ink: #172554; --surface: #fff; --accent: #fbbf24; --space: 1rem; }
body { margin: 0; color: var(--ink); background: #f1f5f9; font: 1rem/1.5 system-ui, sans-serif; }
.page-shell { width: min(calc(100% - 2rem), 68rem); margin-inline: auto; }
.game-shell { padding-block: 2rem; }
.game-header { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 1rem; }
h1 { font-size: clamp(2rem, 5vw, 3.5rem); margin-block: .25rem; }
.eyebrow { font-size: .78rem; font-weight: 800; letter-spacing: .1em; text-transform: uppercase; color: #166534; }
.scoreboard { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: .75rem; margin-block: 1.5rem; }
.scoreboard article { display: grid; gap: .25rem; padding: 1rem; border-radius: .75rem; background: white; border: 1px solid #cbd5e1; }
.scoreboard strong { font-size: 1.8rem; }
.scoreboard small { color: #475569; }
.table-panel { padding: clamp(1rem, 3vw, 2rem); border: 5px solid #166534; border-radius: 1.5rem; background: var(--felt); color: white; }
.table-heading { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: .75rem; }
.game-board { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: clamp(.5rem, 2vw, 1rem); margin-block: 1.5rem; }
.game-card { display: grid; gap: .4rem; align-content: space-between; min-width: 0; min-height: 11rem; padding: .75rem; border: 2px solid white; border-radius: .75rem; background: white; color: var(--ink); font: inherit; text-align: start; box-shadow: 0 .5rem 1rem rgb(0 0 0 / .15); }
.game-card strong { font-size: clamp(1.5rem, 4vw, 2.5rem); }
.game-card small { font-size: .75rem; }
.game-card[aria-pressed="true"] { transform: translateY(-.4rem); border-color: var(--accent); box-shadow: 0 0 0 3px var(--accent); }
.game-actions { display: flex; flex-wrap: wrap; gap: .75rem; margin-block: 1rem; }
.button { border: 2px solid #1d4ed8; border-radius: .5rem; padding: .7rem 1rem; background: #1d4ed8; color: white; font: inherit; font-weight: 700; }
.button-secondary { color: #1d4ed8; background: white; } .button-quiet { color: var(--ink); background: transparent; border-color: #64748b; }
.game-status, .fine-print { color: #475569; }
:focus-visible { outline: 3px solid #f59e0b; outline-offset: 3px; }
@media (max-width: 40rem) { .game-board { grid-template-columns: repeat(2, minmax(0, 1fr)); } .scoreboard { grid-template-columns: 1fr; } }
@media (prefers-reduced-motion: reduce) { .game-card[aria-pressed="true"] { transform: none; } *, *::before, *::after { transition: none !important; } }
